SELECT 
FROM fund_forecast


        AND plan_id = #{params.planId}


        AND forecast_type = #{params.forecastType}


        AND forecast_method = #{params.forecastMethod}


        AND org_id = #{params.orgId}


        AND forecast_date >= #{params.startDate}


        AND forecast_date <= #{params.endDate}


ORDER BY forecast_date DESC, create_time DESC

SELECT 
FROM fund_forecast
WHERE org_id = #{orgId}
AND forecast_date >= #{startDate} AND forecast_date <= #{endDate}
ORDER BY forecast_date DESC

SELECT 
FROM fund_forecast
WHERE org_id = #{orgId}
AND forecast_accuracy >= #{minAccuracy}
AND actual_amount IS NOT NULL
ORDER BY forecast_accuracy DESC

SELECT COUNT(*)
FROM fund_forecast


        AND plan_id = #{params.planId}


        AND forecast_type = #{params.forecastType}


        AND forecast_method = #{params.forecastMethod}


        AND org_id = #{params.orgId}

SELECT COALESCE(AVG(forecast_accuracy), 0)
FROM fund_forecast
WHERE actual_amount IS NOT NULL

    AND plan_id = #{params.planId}


    AND forecast_type = #{params.forecastType}


    AND forecast_method = #{params.forecastMethod}


    AND org_id = #{params.orgId}

SELECT 
    COUNT(*) as totalCount,
    COALESCE(SUM(forecast_amount), 0) as totalForecastAmount,
    COALESCE(SUM(CASE WHEN actual_amount IS NOT NULL THEN actual_amount ELSE 0 END), 0) as totalActualAmount,
    COALESCE(AVG(CASE WHEN actual_amount IS NOT NULL THEN forecast_accuracy ELSE NULL END), 0) as avgAccuracy,
    COUNT(CASE WHEN actual_amount IS NOT NULL THEN 1 END) as verifiedCount,
    COUNT(CASE WHEN forecast_accuracy >= 80 THEN 1 END) as highAccuracyCount
FROM fund_forecast


        AND plan_id = #{params.planId}


        AND forecast_type = #{params.forecastType}


        AND forecast_method = #{params.forecastMethod}


        AND org_id = #{params.orgId}

SELECT DATE_FORMAT(forecast_date, '%Y-%m') as month, COUNT(*) as forecastCount, COALESCE(SUM(forecast_amount), 0) as totalForecastAmount, COALESCE(SUM(CASE WHEN actual_amount IS NOT NULL THEN actual_amount ELSE 0 END), 0) as totalActualAmount, COALESCE(AVG(CASE WHEN actual_amount IS NOT NULL THEN forecast_accuracy ELSE NULL END), 0) as avgAccuracy FROM fund_forecast WHERE org_id = #{orgId}
AND forecast_type = #{forecastType}
AND forecast_date >= DATE_SUB(CURDATE(), INTERVAL #{months} MONTH) GROUP BY DATE_FORMAT(forecast_date, '%Y-%m') ORDER BY month ASC

SELECT forecast_method, COUNT(*) as totalCount, COUNT(CASE WHEN actual_amount IS NOT NULL THEN 1 END) as verifiedCount, COALESCE(AVG(CASE WHEN actual_amount IS NOT NULL THEN forecast_accuracy ELSE NULL END), 0) as avgAccuracy, COALESCE(SUM(forecast_amount), 0) as totalForecastAmount, COALESCE(SUM(CASE WHEN actual_amount IS NOT NULL THEN actual_amount ELSE 0 END), 0) as totalActualAmount, COALESCE(SUM(CASE WHEN actual_amount IS NOT NULL THEN ABS(forecast_amount - actual_amount) ELSE 0 END), 0) as totalDeviation FROM fund_forecast WHERE org_id = #{orgId}
AND forecast_date >= #{startDate}
AND forecast_date <= #{endDate}
GROUP BY forecast_method ORDER BY avgAccuracy DESC

SELECT COUNT(*) > 0
FROM fund_forecast
WHERE forecast_no = #{forecastNo}
